        Phrase("int-01", "اسمي أحمد", "Nama saya Ahmad", "ناما سايا أحمد", "Benim adım Ahmed", "بينيم آدیم أحمد", Register.Neutral, "التعريف بنفسك أول مرة.", "«adım» = اسمي (ad + ملكية). بالإندونيسية nama saya = اسمي — سما ستسمعهما كل يوم.", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-02", "تشرفت بمعرفتك", "Senang berkenalan", "سننݢ بركينالان", "Memnun oldum", "ممنون أولديم", Register.Neutral, "بعد أي تعارف جديد.", "«memnun oldum» حرفيًا: سُررتُ — من memnun (راضٍ، أصل عربي: ممنون!). الشرح: الجملة التركية تسبق أحيانًا بـ«Tanıştığımıza memnun oldum» (سُررت بتعارفنا) في الرسمي.", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-03", "أنا من اليمن / من السعودية", "Saya dari Yaman / dari Arab Saudi", "سايا داري يامان", "Ben Yemenliyim / Suudi Arabistanlıyım", "بين يمنلييم", Register.Neutral, "سؤال سيسألونه لك دائمًا.", "التركية تبني الجنسية بلاحقة -li: Yemen+li. والإندونيسية تستعمل dari (من) — أبسط بناء ممكن.", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-04", "أعيش في جاكرتا / إسطنبول", "Saya tinggal di Jakarta", "سايا تينݢال دي جاكرتا", "İstanbul'da yaşıyorum", "إسطنبولدا ياشيوروم", Register.Neutral, "متابعة التعريف.", "لاحقة المكان: الإندونيسية di قبل المكان، التركية -da/-de ملتصقة. «yaşıyorum» = أعيش (الآن).", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-05", "أنا أتعلم الإندونيسية/التركية", "Saya sedang belajar bahasa Indonesia", "سايا سيدانݢ بلاجر باهاسا إندونيسيا", "Türkçe öğreniyorum", "توركچه أورينيوروم", Register.Neutral, "أهم جملة تعريف للمتعلم — تفتح لك كل تسامح لاحق.", "هذه الجملة جواز مرورك: من يقولها يبطئ الناس له ويصححونه بفرح. belajar = يتعلم، öğreniyorum = أتعلم الآن.", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-06", "أفهم قليلًا فقط — تحدث ببطء رجاءً", "Saya paham sedikit. Tolong pelan-pelan ya", "سايا پاهم سديكيت. تولوڠ پيلان-پيلان يا", "Az anlıyorum, lütfen yavaş konuşun", "أز أنليوروم، لوتفين ياؤاش كونوشون", Register.Neutral, "أول حوار مع أي شخص جديد.", "«yavaş yavaş» و«pelan-pelan» — نفس أسلوب التكرار التلطيفي في اللغتين.", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-07", "عمري ثلاثون سنة", "Umur saya tiga puluh tahun", "أومور سايا تيݢا پولوه تاهون", "Otuz yaşımdayım", "أوتوز ياشيمدايم", Register.Casual, "أسئلة التعارف المتبادلة.", "«umur» إندونيسية من العمر العربية! و«yaş» التركية = عمر. سؤالها: Berapa umur kamu? / Kaç yaşındasın?", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-08", "أتحدث العربية والإنجليزية", "Saya bisa bahasa Arab sama Inggris", "سايا بيسا باهاسا عرب ساما إنݢريس", "Arapça ve İngilizce biliyorum", "أرابتشه ڤيه إنݢيليزجه بيليوروم", Register.Casual, "وصف لغاتك.", "«bisa» = يستطيع/يجيد، و«biliyorum» = أعرف (معلومات/لغات — بينما biliyorum تستخدم للغات لا konuşabiliyorum للكلام).", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-09", "أعمل في التجارة / عندي محل", "Saya dagang. Ada toko sedikit", "سايا داݢانݢ. ادا توكو سديكيت", "Ticaret yapıyorum, bir dükkânım var", "تيجارت يابيوروم بير دوككانيم ڤار", Register.Casual, "تعريف مهني — سيكرره معك كل بائع وزبون.", "«dagang» = يتجر (كلمة سوق المليون!) و«dükkânım var» = عندي دكان — بناء var/yok الذهبي.", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-10", "أنا متزوج / عندي ثلاثة أطفال", "Saya sudah menikah. Anak saya tiga", "سايا سوداه مينيكاه. أناك سايا تيݢا", "Evliyim, üç çocuğum var", "إيڤليم أوتش تشوجوݢوم ڤار", Register.Casual, "تعارف أعمق — شائع في ثقافتي البلدين.", "«çocuğum var» = عندي أطفال — التركية تعبّر بالملك var، والإندونيسية بترتيب اسم+عدد بعده (anak saya tiga = أطفالي ثلاثة).", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("int-11", "من أين أنت؟ (اسأل أنت)", "Kakak dari mana?", "كاكاك داري مانا", "Nerelisiniz?", "نيريليسينيز", Register.Casual, "سؤالك أنت عند التعارف.", "«nereli» = من أي بلد (نسبة) — سؤال الجنسية التركي الأشهر. والإندونيسية dari mana = من أين مباشرة.", "", "academy|الضمائر والتعريف بالنفس", Cefr.A0),
        Phrase("int-12", "هل أنت من هنا؟", "Kakak orang sini?", "كاكاك أورانݢ سيني", "Buranın mısınız?", "بورانين ميسينيز", Register.Casual, "للتعرف على جنس محلك أو منطقتك.", "«orang sini» = شخص هنا — بناء إندونيسي يومي (orang = شخص). التركية: buranın = من هنا.", "", "academy|الضمائر والتعريف بالنفس", Cefr.A1),
        Phrase("que-01", "ما هذا؟ / ماذا تريد؟", "Ini apa? / Mau apa?", "إيني أبا؟ / ماو أبا", "Bu ne? / Ne istersiniz?", "بو نه؟ / نه إسترسينيز", Register.Casual, "أول سؤالين في أي مكان.", "لاحظ بساطة التركيب: الإندونيسية تحذف الفعل كثيرًا (Mau apa = تريد ماذا = ماذا تريد).", "", "academy|أدوات الأسئلة الذهبية", Cefr.A0),
        Phrase("que-02", "لمن هذا؟ / لمن تعمل؟", "Ini punya siapa?", "إيني پونيا سيابا", "Bu kimin?", "بو كيمين", Register.Casual, "الاستفسار عن الملكية.", "«punya» = يملك — كلمة الملكية الإندونيسية الأم. «kimin» = لمن (kim + ملكية).", "", "academy|أدوات الأسئلة الذهبية", Cefr.A1),
        Phrase("que-03", "متى يفتح / متى يصل؟", "Buka kapan? / Sampai kapan?", "بوكا كاڤان؟ / سامپاي كاڤان", "Ne zaman açılır? / Ne zaman gelir?", "نه زمان آتشيلير؟ / نه زمان كيلير", Register.Casual, "دوام المحلات والتوصيل.", "التركية بصيغة المبني للمجهول açılır (يُفتَح) — الأنسب للمحلات والدوام.", "", "academy|أدوات الأسئلة الذهبية", Cefr.A1),
        Phrase("que-04", "أين أجد ...؟ (أقرب ...)؟", "Di mana ada ...? / Di mana yang terdekat?", "دي مانا ادا؟ دي مانا ياڠ تيريديكات", "Nerede ... var? / En yakın ... nerede?", "نيریده ڤار؟ / ين ياقين نيريدة", Register.Casual, "الضياع في مدينة جديدة.", "بناء var/yok التركي (يوجد/لا يوجد) + nerede = أين يوجد. بالإندونيسية di mana ada — نفس المنطق معكوس الترتيب.", "", "academy|أدوات الأسئلة الذهبية", Cefr.A0),
        Phrase("que-05", "كيف أفعل هذا؟ / كيف وصلت لهذا السعر؟", "Gimana caranya?", "كيمانا تارانيا", "Nasıl yapılıyor?", "ناسيل يابيليور", Register.Casual, "طلب شرح الطريقة.", "«caranya» = طريقته (cara طريقة + nya) — أشهر صيغة سؤال شرح في إندونيسيا.", "", "academy|أدوات الأسئلة الذهبية", Cefr.A0),
        Phrase("que-06", "لماذا هذا السعر؟ / لماذا غدًا؟", "Kenapa harganya begini?", "كينابا هارݢانيا بيكيني", "Neden bu fiyat? / Niye yarın?", "نيدن بو فيات؟ / نييه يارين", Register.Casual, "استيضاح بلطف — دبلوماسي.", "«niye» التركية أكثر عفوية من neden. نبرة الاستيضاف أهم من الأداة — ارفع نبرة السؤال وابتسم.", "", "academy|أدوات الأسئلة الذهبية", Cefr.A0),
        Phrase("que-07", "أيّهما أفضل؟ / أي واحد تريد؟", "Yang mana yang lebih bagus?", "ياڠ مانا ياڠ لبيه باݢوس", "Hangisi daha iyi?", "هانݢيسي داها إيي", Register.Casual, "المقارنة والاختيار.", "«yang» الإندونيسية = «الذي» — أداة الربط الأولى. «daha» التركية = أكثر — أداة المقارنة الأولى.", "", "academy|أدوات الأسئلة الذهبية", Cefr.A1),
        Phrase("que-08", "هل يمكن...؟ هل ينفع...؟", "Bisa...?", "بيسا", "...olur mu?", "أولور مو", Register.Casual, "طلب إمكان أي شيء بأدب.", "«Bisa?» كلمة واحدة تكفي بإندونيسيا! و«Olur mu؟» كلمة + mi تكفي بتركيا — أقصر طلب مهذب في اللغتين.", "", "academy|أدوات الأسئلة الذهبية", Cefr.A1),
        Phrase("que-09", "ما معنى هذه الكلمة؟", "Ini artinya apa?", "إيني أرتينيا أبا", "Bu kelime ne demek?", "بو كيليمه نه ديمك", Register.Casual, "تعلّم اللغة باللغة — أهم عادة متعلم.", "«demek» = يعني — فعل المعنى التركي. اجعل هذا السؤال سلاحك اليومي: كل كلمة لا تفهمها اسأل عنها فورًا.", "", "academy|أدوات الأسئلة الذهبية", Cefr.A1),
        Phrase("que-10", "قلت ماذا؟ (لم أسمعك)", "Maaf, tadi bilang apa?", "ماؤف تادي بيلاڠ أبا", "Affedersiniz, ne dediniz?", "أفيدرسينيز نه ديدينيز", Register.Casual, "حل جميع سوء السماع.", "«tadi» = قبل قليل — كلمة زمنية إندونيسية يومية. «ne dediniz» = ماذا قلتم (ماضي الرسمي).", "", "academy|أدوات الأسئلة الذهبية", Cefr.A0),
        Phrase("ver-01", "أريد أن أرى / أريد هذا", "Saya mau lihat dulu / Mau yang ini", "سايا ماو ليهات دولو", "Bakmak istiyorum / Bunu istiyorum", "باكماق إستيوروم", Register.Casual, "التعبير عن الرغبة — أساس كل شيء.", "«istiyorum» = أريد (istemek + الآن) — الفعل الأول في تعلم التركية. بالإندونيسية mau = يريد، بدون تصريف أبدًا.", "", "academy|الأفعال الذهبية العشرون", Cefr.A0),
        Phrase("ver-02", "عندكم...؟ / يوجد هنا...؟", "Ada ... nggak?", "ادا نݢاك", "... var mı?", "ڤار مي", Register.Casual, "السؤال عن أي شيء في الوجود.", "ثنائية ada/nggak وvar/mı — أعلى تردد في أسواق البلدين. «yok» = لا يوجد: «Büyük beden yok» (لا يوجد مقاس كبير).", "", "academy|الأفعال الذهبية العشرون", Cefr.A0),
        Phrase("ver-03", "استطيع أن أدفع بالبطاقة؟", "Bisa bayar pakai kartu?", "بيسا باير پاكاي كارتو", "Kartla ödeyebilir miyim?", "كارتله أوديابيلير ميين", Register.Casual, "كل عملية دفع.", "التركية «-ebilir miyim» = أستطيع...؟ (طلب إذن بالغ اللطف). الإندونيسية bisa تكفي دائمًا.", "", "academy|الأفعال الذهبية العشرون", Cefr.A1),
        Phrase("ver-04", "ساعدني قليلًا / أساعدك؟", "Bantu sebentar ya / Mau saya bantu?", "بنتو سبنتار يا", "Yardımcı olayım mı?", "يارديمجي أولايم مي", Register.Casual, "بناء التحالف اليومي.", "«olayım mı» = هل أكون...؟ — صيغة العرض التركية المهذبة. بالإندونيسية بنية «Mau saya + فعل؟» تعرض الخدمة بلطف.", "", "academy|الأفعال الذهبية العشرون", Cefr.A1),
        Phrase("ver-05", "انتظر لحظة من فضلك", "Tunggu sebentar ya", "تونݢݢ سبنتار يا", "Bir dakika bekleyin lütfen", "بير داقيقا بيكليين لوتفين", Register.Neutral, "إشغال أي شخص بلطف.", "«ya» الختامية الإندونيسية تحوّل الأمر لتوسل ودي — سحر التلطف الواحد.", "", "academy|الأفعال الذهبية العشرون", Cefr.A0),
        Phrase("ver-06", "خذ هذا معك / لا تنسَ حاجتك", "Bawa barangnya ya / Jangan lupa bawa", "باوا باراڠنيا يا", "Yanınızda götürün / Almayı unutmayın", "يانينيزده كوتورون", Register.Casual, "تسليم أغراض.", "«götürmek» يأخذ معه، «getirmek» يجيء به — الثنائية التركية الشهيرة (أخذ للهناك/الإتيان لل هنا).", "", "academy|الأفعال الذهبية العشرون", Cefr.A1),
        Phrase("ver-07", "سأعود فورًا / رجعت", "Bentar ya, saya balik lagi", "بنتار يا سايا باليك لاݢي", "Hemen dönüyorum / Döndüm", "هيمين دونويوروم", Register.Casual, "الانصراف المؤقت من المحل.", "«balik lagi» = يرجع ثانية — التعبير الإندونيسي المشرق المعتاد. جرب قولها لجار دكانك وسترى الابتسام.", "", "academy|الأفعال الذهبية العشرون", Cefr.A1),
        Phrase("ver-08", "لا أفهم هذا / فهمت الآن!", "Saya nggak paham yang ini / Oh, paham sekarang!", "سايا نݢاك پاهم ياڠ إيني", "Bunu anlamıyorum / Anladım şimdi!", "بونو أنلاميوروم", Register.Casual, "لحظات الفهم وسوء الفهم.", "«Anladım!» (فهمت!) — كلمة المتعلم التركي اليومية الأولى. صدّق بها تقدمك.", "", "academy|الأفعال الذهبية العشرون", Cefr.A1),
        Phrase("ver-09", "كُل على مهلك / اشرب وأنت مرتاح", "Makan dulu, pelan-pelan", "ماكان دولو پيلان-پيلان", "Buyurun, afiyet olsun", "بويورون آفيت أولسون", Register.Casual, "دعوة الطعام — ستسمعها كثيرًا.", "«afiyet olsun» = بالعافية — العبارة التركية المقدسة للطعام. اردد عليها «eline sağlık» (ليديك الصحة) عند مضيفك.", "", "academy|الأفعال الذهبية العشرون", Cefr.A1),
        Phrase("ver-10", "افتح لي هذا من فضلك / أغلقه", "Bukain dong / Tutupin ya", "بوكاين دونݢ", "Şunu açar mısınız? / Kapatır mısınız?", "شونو آتشار ميسينيز", Register.Casual, "طلب فتح علب وأكياس وعرض بضاعة.", "اللاحقة الإندونيسية -in/-kan (bukain/tutupin) = افعل لي — عامية الخدمة اليومية. التركية «-ar mısınız» صيغة الطلب المهذبة القياسية.", "", "academy|الأفعال الذهبية العشرون", Cefr.A0),
        Phrase("tim-01", "كم الساعة الآن؟", "Jam berapa sekarang?", "جام براپا سيكارانݢ", "Saat kaç?", "ساعات كاتش", Register.Casual, "أكثر سؤال زمني في اليوم.", "«kaç» = كم — نفس أداة الأرقام. بالإندونيسية jam = ساعة/ساعة زمنية.", "", "academy|الوقت والأيام والتواريخ", Cefr.A1),
        Phrase("tim-02", "المحل يفتح الثامنة ويغلق العاشرة", "Toko buka jam delapan, tutup jam sepuluh malam", "توكو بوكا جام ديلابان", "Dükkân sekizde açılıyor, onda kapanıyor", "دوككان سيكيزده آتشيليور", Register.Casual, "إعلام الزبائن بالدوام.", "التركية «-de» = في (الساعة): sekiz**de** = في الثامنة. لافتة الدوام: AÇIK (مفتوح) / KAPALI (مغلق).", "", "academy|الوقت والأيام والتواريخ", Cefr.A1),
        Phrase("tim-03", "الشحنة تصل غدًا مساءً", "Kirimannya besok malam sampai", "كيريمانيا بيسوك مالام سامپاي", "Kargo yarın akşam gelir", "كارݢو يارين آقشام كيلير", Register.Casual, "مواعيد التسليم.", "ترتيب الإندونيسية هنا حر — المهم الكلمات. التركية تضع الفعل آخرًا دائمًا: yarın akşam gelir.", "", "academy|الوقت والأيام والتواريخ", Cefr.A1),
        Phrase("tim-04", "اليوم جمعة — المحل مغلق وقت الصلاة", "Hari ini Jumat, toko tutup sekitar jam dua belas", "هاري إيني جومعة", "Bugün cuma, öğlen kapalıyız", "بوكون قوما", Register.Casual, "إدارة إيقاع الجمعة الديني.", "في إندونيسيا وتركيا معًا: الجمعة تخف حركة الأسواق وقت الصلاة — أعلنها لزبائنك بوضوح وكسب ثقتهم.", "", "academy|الوقت والأيام والتواريخ", Cefr.A1),
        Phrase("tim-05", "بعد ساعة أكون عندك", "Satu jam lagi saya kesana", "ساتو جام لاݢي سايا كسانا", "Bir saat sonra gelirim", "بير ساعات سونرا كيليريم", Register.Casual, "مواعيد اللقاءات والتوصيل.", "«lagi» = بعد/إضافي — كلمة «بعد» السوقية. «sonra» التركية = بعد — أنقى كلمة زمن سوقية.", "", "academy|الوقت والأيام والتواريخ", Cefr.A1),
        Phrase("tim-06", "كم يومًا يستغرق؟", "Berapa lama? / Butuh berapa hari?", "براپا لاما", "Kaç gün sürüyor?", "كاتش كون سوريور", Register.Casual, "مهل الطلبات والخدمات.", "«sürmek» = يستغرق/يمتد — فعل المدد الزمنية التركي الأول. بالإندونيسية berapa lama = كم المدة.", "", "academy|الوقت والأيام والتواريخ", Cefr.A1),
        Phrase("tim-07", "عطلة الأسبوع القادم نستلم جديدًا", "Minggu depan kami libur / masuk barang baru", "مينݢو ديبان كامي ليبور", "Gelecek hafta izinliyiz / yeni mal geliyor", "كيليجك هافتا ييزينلييز", Register.Casual, "تنسيق العطلات.", "«libur» إندونيسية من الهولندية، و«izin» التركية من الإذن العربية! — كلمتا العطلة في البلدين من عروق حضارية متصلة.", "", "academy|الوقت والأيام والتواريخ", Cefr.A1),
        Phrase("tim-08", "في أقرب وقت / فورًا إن أمكن", "Secepatnya ya / Semampunya", "ستشياتنيا يا", "En kısa zamanda / hemen mümkünse", "ين قصا زاماندا", Register.Neutral, "طلبات الاستعجال المهذبة.", "«secepatnya» = بأسرع ما يمكن (se- + cepat + -nya) — بناء التفصيل الإندونيسي الأنيق.", "", "academy|الوقت والأيام والتواريخ", Cefr.A1),
        Phrase("fee-01", "كيف حالك؟ / بخير الحمد لله", "Apa kabar? / Baik, alhamdulillah", "أبا كابر؟ / باءيك الحمدلله", "Nasılsınız? / İyiyim, elhamdülillah", "ناسيلسينيز؟ / إييم الحمدولله", Register.Neutral, "التحية الثانية بعد السلام — يومية إلزامية.", "«elhamdülillah» التركية من الحمد لله العربية — استعملها ستدمج فورًا. الرد الإندونيسي الدافئ: «Baik-baik aja» (تمام تمام).", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-02", "أنا تعبان اليوم / متعب جدًا", "Hari ini saya capek sekali", "هاري إيني سايا تشابيك سيكالي", "Bugün çok yorgunum", "بوكون تشوك يوركونوم", Register.Casual, "حالتك مع الجيران والزبائن الدائمين.", "«yorgunum» = أنا متعب (yorgun + um) — اللاحقة تحمل أنا. بالإندونيسية capek من العمل، sakit للمرض — فرق دقيق.", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-03", "الحمد لله على السلامة! (للمتعافي/العائد)", "Syukur sudah sembuh!", "شكور سوداه سمبوه", "Geçmiş olsun!", "كيتميش أولسون", Register.Casual, "من مرض أو مصيبة — مجاملة واجبة.", "«Geçmiş olsun» = ليكن قد مضى — أعظم عبارة مواساة تركية، تقال للمريض وحتى لمن تعطلت سيارته!", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-04", "هذا أجمل من ذاك / الأفضل على الإطلاق", "Ini lebih cantik dari yang itu / Yang paling bagus ini", "إيني لبيه تشانتيك", "Bu ondan daha güzel / En güzeli bu", "بو أوندان داها كوزيل", Register.Casual, "المقارنة — لب البيع والاختيار.", "ثنائية lebih/paling الإندونيسية وdaha/en التركية — أربع كلمات تفتح لك كل المقارنات في اللغتين.", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-05", "لا بأس، خذها ببساطة", "Santai aja, kak", "سانتاي أجا كاك", "Sakin ol, sorun yok", "ساكين أول سورون يوك", Register.Casual, "تهدئة أي توتر أو استعجال.", "«santai» = مرتاح/بارد — روح إندونيسيا في كلمة. «sakin ol» = اهدأ — التهدئة التركية القياسية.", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-06", "أنا سعيد بخدمتك / خدمتك تشرّف", "Senang bisa bantu kakak", "سننݢ بيسا بنتو كاكاك", "Size hizmet etmek mutluluk", "سيزه خدمات إتميك موتلولوق", Register.Casual, "ختام معاملة جميلة.", "البائع الذي يقولها مخلصًا يبني ولاءً — ترسل بالرسائل أيضًا كإغلاق راقٍ.", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-07", "أنا مشغول الآن — لحظة واحدة", "Saya lagi sibuk, bentar ya", "سايا لاݢي سيبوك بنتار يا", "Şu an meşgulüm, bir saniye", "شو آن مشكولوم بير سانييه", Register.Casual, "إدارة الازدحام بلطف.", "«lagi/lagi» الإندونيسية = الآن (حال مستمر) — «lagi sibuk» = مشغول الآن. «meşgulüm» = أنا مشغول (من المشغول العربية!).", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-08", "الله يعطيك العافية / على بركة الله", "Semoga lancar ya!", "سمواݢا لانتشار يا", "Kolay gelsin! / Hayırlısı olsun", "قولاى كيلسين", Register.Casual, "دعوات العمل اليومية.", "«Kolay gelsin» لمن يعمل و«hayırlısı olsun» = ليكن ذا خير — دعوتان تركيتان تصنعان ودًا فوريًا. والإندونيسية «Semoga lancar» = ليكن سلسًا.", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-09", "الحمد لله، الأمور بخير", "Alhamdulillah, lancar-lancar aja", "الحمدلله لانتشار-لانتشار أجا", "İyiyiz, elhamdülillah", "إيييز الحمدولله", Register.Casual, "جواب «كيف الأعمال؟».", "«lancar» = سائل/سلس — وصف الأعمال الجارية بلا عوائق — كلمة سوق إندونيسية محبوبة جدًا.", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("fee-10", "لا تقلق / لا تستعجل على نفسك", "Jangan khawatir, pelan-pelan", "جانڠ خاواتير پيلان-پيلان", "Merak etme, acele etme", "مراك إتمه أجهله إتمه", Register.Casual, "طمأنة زبون أو صديق قلق.", "«khawatir» إندونيسية أصلها من القلق العربية عبر الجاوية! التراث العربي حي في كلمات اللغتين أكثر مما تتخيل.", "", "academy|الصفات والمشاعر والمقارنة", Cefr.A1),
        Phrase("the-01", "أريد آكل شيئًا ساخنًا/باردًا", "Mau makan yang anget / dingin", "ماو ماكان ياڠ أنݢيت", "Sıcak/soğuk bir şey yemek istiyorum", "سيتشق بير شيه ييميك إستيوروم", Register.Casual, "في أي مطعم أو بيت مضيف.", "«anget» عامية hangat (دافئ) — كلمة طعام يومية. التركية تبني بترتيب: وصفة + شيء + مصدر + أريد.", "", "academy|المفردات الموضوعية الكبرى", Cefr.A0),
        Phrase("the-02", "وين أقرب صيدلية/مستشفى؟", "Apotek terdekat di mana?", "أپوتيك تيريديكات دي مانا", "En yakın eczane nerede?", "ين ياقين إيتشانه نيريدة", Register.Casual, "حالات صحية عاجلة.", "«en yakın» = الأقرب (en + yakın) — صيغةSuperlative التركية. احفظها مع أي مكان: en yakın banka/otogar.", "", "academy|المفردات الموضوعية الكبرى", Cefr.A1),
        Phrase("the-03", "رأسي يؤلمني منذ أمس", "Kepala saya sakit dari kemarin", "كيبالا سايا ساكيت داري كيمارين", "Dünden beri başım ağrıyor", "دوندن بيري باشيم آرييور", Register.Casual, "وصف عارض صحي للطبيب/الصيدلي.", "«-den beri» = منذ — أداة «منذ» التركية. بالإندونيسية dari = من/منذ معًا — كلمة واحدة لكلا الاستخدامين.", "", "academy|المفردات الموضوعية الكبرى", Cefr.A1),
        Phrase("the-04", "كيف آخذ هذا الدواء؟", "Obat ini gimana minumnya?", "أبات إيني كيمانا مينومنيا", "Bu ilaç nasıl kullanılır?", "بو إيلاتش ناسيل كولانيلير", Register.Casual, "في الصيدلية — سؤال يهم حياتك.", "«minumnya» = شربه (minum + nya) — بناء إندونيسي يشبه «طريقة شربه». التركية kullanılır = يُستعمل (مبني للمجهول رسمي).", "", "academy|المفردات الموضوعية الكبرى", Cefr.A1),
        Phrase("the-05", "خذني لهذا العنوان من فضلك (تاكسي)", "Ke alamat ini ya, pak", "كه ألامت إيني يا پاك", "Bu adrese lütfen", "بو أدرسه لوتفين", Register.Casual, "أول جملة توصيل.", "«Ke» = إلى (حركة نحو) مقابل «di» (استقرار). التركية adrese = إلى العنوان (-e لاحقة الاتجاه).", "", "academy|المفردات الموضوعية الكبرى", Cefr.A0),
        Phrase("the-06", "بخطأ المستخدم أقصد يمين لا يسار", "Maksud saya kanan, bukan kiri!", "مقصود سايا كانان بوكان كيري", "Sağ diycektim, sol değil!", "صاغ دييجكتيم", Register.Casual, "تصحيح اتجاه سريع.", "«maksud saya» = قصدي — عبارة التصحيح الإندونيسية الأولى. التركية «-yecek + -ti» = كنت سأقول — ماضٍ مستقبلي أنيق!", "", "academy|المفردات الموضوعية الكبرى", Cefr.A1),
        Phrase("the-07", "الجو جميل اليوم / تمطر كثيرًا", "Hari ini cuacanya bagus / Hujan deras sekali", "هاري إيني تشواتشانياباݢوس", "Bugün hava güzel / Çok yağmur yağıyor", "بوكون هاڤا كوزيل", Register.Casual, "دردشة الطقس — فاتحة حديث عالمية.", "«hava» التركية = جو/هواء — «hava nasıl?» (كيف الجو؟) فاتحة حديث يومية. بالإندونيسية cuaca = طقس.", "", "academy|المفردات الموضوعية الكبرى", Cefr.A1),
        Phrase("the-08", "الله يوفقك في عملك (وداع نهاري)", "Semoga sukses ya!", "سمواݢا سوكسيس يا", "Kolay gelsin, başarılar!", "قولاى كيلسين بشريلار", Register.Casual, "وداع أي شخص يعمل.", "«Başarılar!» = نجاحات! — وداع الترك المتفائل. أما «Kolay gelsin» فتُقال لمن ترك عمله للتو أو مستمرًا فيه.", "", "academy|المفردات الموضوعية الكبرى", Cefr.A1),
        Phrase("the-09", "أشتقت إليك / زمان عنك!", "Kangen nih! Lama nggak ketemu", "كانݢين نيه! لاما نݢاك كتيمو", "Seni özledim / Uzun oldu görüşmeyeli", "سني أوزليديم", Register.Slang, "لقاء صديق/زبون دائم غاب طويلًا.", "«kangen» الجاوية = شوق — أدفأ كلمة لقاء إندونيسية. «özledim» من özlem (شوق) — التركية تقولها للأصدقاء بلا حرج.", "", "academy|المفردات الموضوعية الكبرى", Cefr.A1),
        Phrase("the-10", "لا أستطيع الآن، عندي التزام عائلي", "Nanti dulu deh, ada acara keluarga", "نانتي دولو ديه ادا آتشارا كيلوارݢا", "Şimdi olmaz, ailevi bir işim var", "شيمي أولماز آيليڤي بير إيشيم ڤار", Register.Casual, "اعتذار مهذب عن دعوة.", "«acara keluarga» = مناسبة عائلية — عذر لا يُرد في إندونيسيا! التركية «işim var» = عندي شغل — الاعتذار المهني المقبول.", "", "academy|المفردات الموضوعية الكبرى", Cefr.A1),
        Phrase("att-01", "تفضّل / تفضّلي", "Silakan, kak!", "سيلاكان كاك", "Buyurun!", "بويورون", Register.Neutral, "الزعيم المطلق لجذب الزبون: عند الباب، عند توقفه أمام البضاعة، عند تردده.", "«Silakan» و«Buyurun» أعظم كلمتين في البيع باللغتين — تعني تفضل/ادخل/تفضل بعدك/خذ. «kak» مخاطبة ودودة لمن هم في عمرك تقريبًا. التكرار «Buyurun, buyurun!» يعني تفضلوا (لجماعة).", "Buyurun حرفيًا: أمِرْ/تفضل بأمر — أصلها أمر بالفعل buyurmak.", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-02", "تفضل، شوف على راحتك", "Silakan dilihat-dilihat dulu", "سيلاكان ديليهات-ديليهات دولو", "Şöyle bir bakın isterseniz", "شويه بير باكين إسترسينيز", Register.Neutral, "لمن يقف مترددًا أمام المحل — تدعوه دون أي ضغط.", "تكرار الفعل «dilihat-dilihat» في الإندونيسية يعني «تفرّج وتفرّج» أي براحتك وبلا التزام — النبرة الهادئة نفسها بالتركية مع «isterseniz» (إن أردت).", "حرفيًا: تفضّل يُنظَر-يُنظَر أولًا.", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-03", "مرّ ولو للسلام (يا هلا)", "Mampir dulu, kak!", "مامپير دولو كاك", "Uğrayın, çay içelim", "اوكراين، تشاي إتشيليم", Register.Casual, "أسلوب سوق شعبي إندونيسي دافئ لدعوة المارّة. التركية للعلاقات الودّية لا لكل مارّ.", "«Mampir» = اتفضّل بالمرور — لا مكافئ عربي دقيق. بالتركية «uğrayın» دعوة صادقة من بائع تعرفه، وأضفنا «نشرب شاي» لأنها طريقة الأتراك الفعلية!", "", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-04", "عندنا أشياء جميلة", "Ada barang bagus, kak", "ادا باراڠ باݢوس كاك", "Güzel ürünlerimiz var", "كوزيل أورونلريميز ڤار", Register.Casual, "نداء عام للمارّة أمام البسطة أو المحل.", "التركية تفضل بناء «var» (يوجد) — «Güzel şeyler var içinde» (في الداخل أشياء جميلة) أدفأ وأكثر سوقية.", "", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-05", "شوف هذا / شوفي هذا", "Coba lihat yang ini, kak", "تشوبا ليهات ياڠ إيني كاك", "Şuna bir bakın", "شونا بير باكين", Register.Casual, "لفت انتباه زبون متوقف إلى منتج محدد بين يديك.", "«Coba» = جرّب/حاول — كلمة السحر الإندونيسية التي تليّن أي دعوة. بالتركية «şuna» (لهذا) أقوى وأقرب من «bu» لأنها تشير بإصبع العين.", "", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-06", "يمكن يعجبك هذا", "Mungkin kakak suka yang ini", "مونݢكين كاكاك سوكا ياڠ إيني", "Belki bu hoşunuza gider", "بلكي بو هوشونوزا كيدر", Register.Neutral, "عرض ناعم غير مباشر لزبون متفرج — لا يقول «اشترِ» بل يفتح بابًا.", "بالتركية الرسمية «hoşunuza gider» = يمسّ استحسانك. النسخة العفوية: «Belki beğenirsiniz» (ربما تعجبك).", "", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-07", "عندنا شيء ممكن يناسبك", "Ada yang cocok buat kakak", "ادا ياڠ تشوتشوق بوات كاكاك", "Size uygun bir şeyimiz var", "سيزه أوݢون بير شيينيميز ڤار", Register.Neutral, "عندما يبدو الزبون باحثًا عن شيء معين.", "«cocok» الإندونيسية = متناسب كالقفاز — كلمة يستعملها الباعة يوميًا. بالتركية «uygun» = ملائم.", "", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-08", "إذا تحب أوريك", "Mau saya tunjukkan?", "ماو سايا تونجوكان", "Göstereyim mi?", "كوستيريم مي", Register.Neutral, "سؤال إذن لطيف قبل أن تمد يدك للمنتج — يعطي الزبون السيطرة.", "أول تعليمات البيع الاحترافي بالغرب والشرق: اسأل قبل العرض. صيغة «mi» التركية بأسلوب السؤال تجعلها عرضًا لا أمرًا.", "", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-09", "لا تتردد / لا تتحشم", "Jangan sungkan, kak", "جانڠ سونݢكان كاك", "Çekinmeyin", "تشيكينمين", Register.Neutral, "لمن يبدو خجولًا من كثرة الأسئلة أو اللمس.", "«sungkan» كلمة إندونيسية عالية الذوق تعني التحشم من إثقال صاحب المحل — لا وجود لكلمة عربية مطابقة، لكن معناها: البيت بيتك. «Çekinmeyin» = لا ترتبك/لا تخجل.", "", "sales|جذب انتباه الزبون", Cefr.A1),
        Phrase("att-10", "خذ راحتك / على مهلك", "Pelan-pelan saja, kak", "پيلان-پيلان ساچا كاك", "Rahat rahat bakın", "راهت راهت باكين", Register.Casual, "لزبون يستعجل نفسه أو يعتذر عن وقته الطويل.", "«pelan-pelan» = ببطء وببطء — التكرار يهدّئ النبرة فعلًا. بالتركية تكرار «rahat rahat» يعطي الإحساس نفسه: خذ كل وقتك.", "", "sales|جذب انتباه الزبون", Cefr.A1),
