        Phrase("wel-18", "كيف حالك اليوم؟ (كسر الجليد)", "Gimana kabarnya hari ini, kak?", "كيمانا كابارنيا هاري إيني كاك", "Nasılsınız bugün, iyi misiniz?", "ناسيلسينيز بوكون، إيي ميسينيز", Register.Casual, "زبون دائم أو جو هادئ يسمح بحديث قصير.", "«Apa kabar?» أشهر من «Gimana kabarnya» لكن الثانية أدفأ وأكثر سوقية. بالتركية السؤال المزدوج (كيفك؟ بخير؟) يعبّر عن اهتمام مضاعف.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-19", "عيدكم مبارك / رمضان كريم (ترحيب موسمي)", "Selamat Hari Raya! / Selamat berpuasa!", "سيلامات هاري رايا! / سيلامات بورواسا", "İyi bayramlar! / Hayırlı ramazanlar!", "إيي بيراملار! / خايرلي رامازانلار", Register.Neutral, "الأعياد والمناسبات — تكسب بها قلوبًا موسمية.", "في إندونيسيا أكبر مسلمي العالم: «Selamat Hari Raya» لعيد الفطر و«Selamat berpuasa» بداية الصوم. بتركيا «İyi bayramlar» تُقال في العيدين، وأضف «bereket» (بركة) للتهاني.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-20", "احجزتَ لنا فرحًا بقدومك (مجاملة تركية)", "", "—", "Sizi görmek güzel, hoş geldiniz!", "سيزي كورميك كوزيل، هوش كيلدينيز", Register.Neutral, "زبون مميز تدخل محلك — مجاملة صادقة النبرة.", "جميل أن تكسر الروتين بجملة إنسانية قصيرة. لاحظ: للإندونيسية بديل عفوي: «Wah, bak siapa datang!» (انظر من أتى!) — تقال ضاحكًا للأصدقاء الدائمين.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-21", "تفضل، الجديد وصل بالأمس", "Silakan kak, yang baru kemarin datang", "سيلاكان كاك، ياڠ بارو كيمارين داتنݢ", "Buyurun, dün yeni ürünler geldi", "بويورون، دون ييني أورونلر كيلدي", Register.Casual, "ترحيب مع طُعم — لزبون يعرف محلك.", "دمج الترحيب بخبر جديد = ترحيب يبيع. «kemarin» أمس و«dün» أمس — كلمتان ستستخدمهما يوميًا.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-22", "خذ راحتك، أنا هنا إن احتجت شيئًا", "Pelan-pelan saja kak, kalau butuh panggil saja", "پيلان-پيلان ساچا كاك، كالاو بوتيه بانݢيل ساچا", "Rahat rahat bakın, bir şeye ihtiyacınız olursa ben buradayım", "راهت راهت باكين، بير شيه إحتيياجينيز أولورسا بين بوردايم", Register.Neutral, "أنسب جملة للزبون الهادئ أو الخجول — تعلن وجودك دون مراقبة.", "هذه الجملة الذهبية تحل معضلة «أُلاحق الزبون أم أتركه؟» — الجواب الاحترافي: أعلن توافرك ثم انسحب. سيتواصل معك حين يرتاح.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-23", "الحمد لله على السلامة! (عاد من سفر/مرض)", "Syukur sudah sembuh / sudah kembali", "شكور سوداه سمبوه / سوداه كمبالي", "Hoş geldiniz, iyi ki döndünüz", "هوش كيلدينيز، إيي كي دوندونوز", Register.Casual, "زبون دائم عاد بعد غياب له سبب معلوم.", "ملاحظة الغياب وأسبابه تعني أنك تهتم به كإنسان لا كمحفظة. بالإندونيسية «syukur» (شكر/حمد) كلمة عربية الأصل يستعملها الجميع.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-24", "هلا وغلا! وين كنت مختفي؟", "Gara-gara apa, kak? Kok lama?", "كارا-كارا أبا كاك؟ كوك لاما", "Nerelerdeydin abi, yoksa unuttun mu bizi?", "نيريليريدين آبي، يوكسه أونوتون مو بيزي", Register.Slang, "مزاح مع زبون دائم صديق — فقط مع من يقبل المزاح.", "«kok» أداة استفهام تعجبية إندونيسية (كيف/لماذا إذن!). «هل نسيتنا؟» دعابة تركية دارجة بين البائع والزبون الصديق. اعرف حدود كل زبون.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-25", "أهلًا بالجيران!", "Wah, tetangga kita! Silakan!", "واه، تيتانݢا كيتا! سيلاكان", "Komşu hoş geldin!", "قومشو هوش كيلدين", Register.Casual, "زبون من نفس الحي — سلّم على الجوار.", "«الجار ثم الدار» — في البلدين ثقافة الجوار حية جدًا، وجملة كهذه تبني ولاءً لا يشتريه إعلان. «komşu» جار — كلمة تركية ذات مكانة دينية/شعبية عالية.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-26", "بقدومك تفتح النفس (مجاملة)", "Ditunggu terus, kak", "ديتونݢݢ تيروس كاك", "Yüzünüzü görmek güzellik verdi", "يوزونوزو كورميك كوزيليك ڤيردي", Register.Slang, "مجاملة قصيرة لزبون محبب.", "«ditunggu terus» = نُنتظرك دائمًا — تأكيد وفاء إندونيسي. بالتركية «منظر وجهك أضاف جمالًا» — أدب اجتماعي راقٍ شائع.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-27", "احجزتَ لنا نور اليوم", "Alhamdulillah, dikirim rezeki hari ini", "الحمدلله، ديكيريم ريزقي هاري إيني", "", "—", Register.Slang, "إندونيسيا فقط: تعبير ديني-سوقي عن فرحك بزبون.", "«rezeki» (رزق) كلمة مركزية في ثقافة البيع الإندونيسية: الزبون رزق مرسل. قولها أمام زبون مسلم إندونيسي تُبنى جسور فورًا. للتركية بديل أدبي: «bereket» البركة.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("wel-28", "هل صعب عليك الوصول؟ (خدمة راقية)", "Susah cari toko kami, kak?", "سوساه تشاري توكو كامي كاك", "Bizi bulmakta zorlandınız mı?", "بيزي بولمقتا زورلاندينيز مي", Register.Formal, "زبون جديد وصل متأخرًا أو مرتبكًا.", "سؤال خدمي لطيف يفتح حديث الاتجاهات ويعطي انطباع احترافية. صيغة «mı» التركية هنا للسؤال المهذب.", "", "sales|الترحيب بالزبائن", Cefr.A1),
        Phrase("adr-01", "تعالي شوف هذا (لمرأة قريبة من عمرك)", "Mampir sini, mbak, lihat yang ini", "مامپير سيني مباك، ليهات ياڠ إيني", "Abla, gel şuna bir bak", "آبلا، كيل شونا بير باك", Register.Casual, "زميلة/زبونة شابة تقف بعيدًا عن المنتج.", "لاحظ: لا يوجد «تعالي» مؤنث في الفعل — الإنجاز كله بالكنية mbak وabla. «Mampir sini» = مرّي إلى هنا — أخف من «datang sini» (تعالي) التي قد تبدو أمرًا جافًا.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-02", "تعال شوف هذا (لرجل قريب من عمرك)", "Coba lihat yang ini, mas", "تشوبا ليهات ياڠ إيني ماس", "Gel bakalım abi, şöyle", "كيل باكاليم آبي، شويه", Register.Casual, "زبون شاب يمشي قرب البسطة.", "«bakalım» = لننظر (صيغة «لن» المشتاقة) — دعوة مشاركة لا أمر. بالإندونيسية «coba» (جرّب) تحويل أي طلب إلى اقتراح لطيف.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-03", "انظري هذا (لفتاة صغيرة/مراهقة)", "Dik, lihat ini deh", "ديك، ليهات إيني ديه", "Kızım, bak şuna", "قيزيم، باك شونا", Register.Slang, "بائع أكبر يخاطب مراهقة — دافئ أبوي.", "«Dik» اختصار adik (أصغر) — محببة جدًا للصغار. «kızım» (ابنتي) من كبير سن لطيفة كالأب؛ من شاب غريب قد توحي غلط — عندها استخدم «hanım» أو اكتف بـ«buyurun».", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-04", "انظر هذا (لشاب صغير)", "Dik, coba yang ini", "ديك، تشوبا ياڠ إيني", "Kardeşim, bak şuna", "كارديشيم، باك شونا", Register.Slang, "مراهق أو شاب صغير السن.", "«kardeşim» (أخي الأصغر) تعادل «يا أخي» العربية — تكسر الحواجز فورًا وتستعملها حتى مع أقرانك.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-05", "هذا يناسبك، تفضّل (لكبير في السن)", "Silakan lihat yang ini, Bu. Bagus, lho.", "سيلاكان ليهات ياڠ إيني بو. باݢوس لوهو", "Buyurun teyze, bakın şuna, güzel", "بويورون تييزه، باكين شونا، كوزيل", Register.Casual, "زبون/زبونة كبيرة في السن — اقترب أنت منها.", "مع الكبار لا تطلب منهم الحركة؛ اذهب أنت واعرض. «lho» جزيئة إندونيسية تعجبية لطيفة تعني «حقًا!». التركية تحفظ ترتيب المهذب: buyurun أولًا.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-06", "تفضل بمشاهدة هذا المنتج (رسمي)", "Silakan lihat produk ini, Bapak", "سيلاكان ليهات پروديك إيني باپاك", "Şu ürüne bakabilirsiniz", "شو أورونه باكابيليرسينيز", Register.Formal, "زبون رسمي أو في معاملة تجارية.", "التركية الرسمية تلجأ لصيغة القدرة «-abilir» (تستطيع) — أخطر فرق عن العربية: لا يوجد أمر هنا إطلاقًا. الإندونيسية تكتفي بإضافة Bapak.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-07", "انظروا جميعًا هذا (لمجموعة)", "Mari lihat yang ini semuanya", "ماري ليهات ياڠ إيني سموانيا", "Bakın şuna hep birlikte", "باكين شونا هيپ بيرليكته", Register.Casual, "عرض جماعي أمام عائلة أو أصدقاء.", "«hep birlikte» = كلنا معًا — روح جماعية تركية. قرار الشراء الجماعي أهم فرصة للبائع: أقنع واحدًا يقنع البقية.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
