        Phrase("adr-09", "متى تقول sen ومتى siz؟ (التركية)", "", "—", "Sen yerine siz kullanın", "سين ييرينه سيز كولانين", Register.Formal, "قاعدة السلوك التركي رقم 1.", "siz للغريب والكبير والزبون (حتى لو أصغرك!). sen للأصدقاء ومن داعبك أولًا. زبون يقول لك «abi sen» = فتح لك باب الصداقة — يجوز لك sen بعدها.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-10", "متى تقول Anda؟ (الإندونيسية)", "Anda mau yang mana?", "اندا ماو ياڠ مانا", "", "—", Register.Formal, "كتابة/رسمي/مقابلات. في السوق اليومي نادر.", "«Anda» أنت الرسمية القياسية لكنها في السوق تبدو مثل «سيادتك» العربية — باردة. البديل الحي: كنية + جملة عادية: «Kak mau yang mana?»", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-11", "لا تخاطب الزبون بـ kamu (مصيدة العرب بالإندونيسية)", "Jangan pakai \"kamu\" ke pembeli", "جانڠ پاكاي كامو ك PEMBELI", "Müşteriye \"sen\" ile başlamayın", "موشتيريه سين إيله باشلاماين", Register.Neutral, "قاعدة احترازية للعرب.", "العرب يتعلمون «kamu = أنت» من الكتب ثم يستخدمونها للزبائن — فتبدو مخاطبة طفل أو صديق حميم. استعمل kak/mbak/mas/Bu/Pak بدلًا منها دائمًا.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-12", "ماذا أقول إن لم أعرف العمر أو المكانة؟", "Kak! (آمنة لكل الأعمار المتقاربة)", "كاك!", "Buyurun! + ابتسامة (آمنة للجميع)", "بويورون!", Register.Neutral, "لحظة الشك الأولى مع أي زبون.", "حين لا تجزم: بالإندونيسية «kak»، بالتركية «buyurun». كلمتان لا تخطئان أبدًا، ثم تتكيف بعد أول تبادل حديث.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A0),
        Phrase("adr-13", "مخاطبة الطفل الصغير جدًا (تحت 10)", "Nak, mau lihat yang ini?", "ناك، ماو ليهات ياڠ إيني", "Oğlum/kızım, şuna bak", "أولوم/قيزيم، شونا باك", Register.Slang, "طفل مع أمه في المحل — كسب الطفل = كسب الأم.", "«Nak» من أنق (عزيزي) — حلوة جدًا. الأتراك يخاطبون الطفل oğlum/kızım ويعطونه اهتمامًا مبالغًا محببًا — افعله.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-14", "«أستاذي» التركية للزبون الذي يبدو متعلمًا", "", "—", "Buyurun hocam", "بويورون هوجام", Register.Casual, "زبون بنظارة/مهندم/يتكلم بثقافة.", "«hocam» (أستاذي) أعظم مجاملة تركية شعبية — تُقال للمعلمين والأطباء وأي شخص يبدو أعلم منك. ستلفت انتباه الزبون بإيجابية مضمونة.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-15", "كنية الزبون الدائم التركي المميز", "", "—", "Buyurun paşam!", "بويورون پاشام", Register.Slang, "زبون دائم تحب مداعبته.", "«paşam» (يا باشا) — مخاطبة عثمانية داعبة تعامل الزبون كأمير. استعملها مرة كل زيارة لا كل جملة.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("adr-16", "متى تكون مخاطبة المرأة مختلفة فعلًا؟", "Mbak untuk muda, Bu untuk dewasa", "مباك أونتوق مودا، بو أونتوق ديواسا", "Abla genç için, hanımefendi resmi", "آبلا كينتش إيتشين، هانيميفندي ريسمي", Register.Neutral, "خلاصة الفصل في سطر واحد.", "الفرق كله في الكنية: شابة=mbak/abla، ناضجة=Bu/hanım، كبيرة=teyze. الأفعال والمحتوى واحد — ركّز طاقتك على اختيار الكنية الصحيحة فقط.", "", "sales|المخاطبة حسب الجنس والعمر", Cefr.A1),
        Phrase("pro-01", "هذا جديد", "Ini barang baru", "إيني باراڠ بارو", "Bu yeni", "بو ييني", Register.Casual, "أول وصف لأي منتج وصل حديثًا.", "«barang» = بضاعة/شيء — كلمة السوق الأم. بالتركية يكفي «Bu yeni» (هذا جديد) — الأتراك يقتصدون في الوصف ويبالغون في الثقة.", "", "sales|عرض المنتجات ووصفها", Cefr.A1),
        Phrase("pro-02", "هذا أفضل من ذاك", "Ini lebih bagus dari yang itu", "إيني لبيه باݢوس داري ياڠ إيتو", "Bu ondan daha iyi", "بو أوندان داها إيي", Register.Casual, "زبون يقارن بين خيارين أمامك.", "«lebih» = أكثر — أداة المقارنة الوحيدة التي تحتاجها. بالتركية «daha» نفس الوظيفة. اذكر بعدها لماذا أفضل: lebih awet (أدوم)، daha sağlam (أمتن).", "", "sales|عرض المنتجات ووصفها", Cefr.A1),
